from curl_cffi import requests

def fetch_marketplace_sku(product_id: str, app_session_token: str):
    url = "https://gql.tokopedia.com/graphql/ProductDetailQuery"
    headers = {
        "User-Agent": "okhttp/4.9.2 TokopediaAndroid/3.245",
        "X-Device-Id": "android-prod-9a7c81d2e",
        "Authorization": f"Bearer {app_session_token}"
    }
    payload = [{
        "operationName": "ProductDetailQuery",
        "variables": {"shopDomain": "", "productKey": product_id},
        "query": "query ProductDetailQuery($productKey: String!) { productDetail(key: $productKey) { id name price { value currency } stock { status available } } }"
    }]
    resp = requests.post(url, headers=headers, json=payload, impersonate="chrome120")
    if resp.status_code == 200:
        return resp.json()[0]["data"]["productDetail"]
    raise ConnectionRefusedError(f"Rejected with status: {resp.status_code}")

import httpx
import asyncio

async def fetch_lpse_tenders(client: httpx.AsyncClient, portal_domain: str):
    endpoint = f"https://{portal_domain}/eproc4/dt/lelang"
    params = {"draw": 1, "start": 0, "length": 50}
    try:
        res = await client.get(endpoint, params=params, timeout=15.0)
        if res.status_code == 200:
            payload = res.json()
            return payload.get("data", [])
    except httpx.RequestError as exc:
        print(f"Portal {portal_domain} unreachable: {exc}")
    return []

import { serve } from "https://deno.land/std@0.177.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.7.1";

serve(async (req) => {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return new Response("Unauthorized", { status: 401 });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_ANON_KEY")!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data, error } = await supabase
    .from("executive_kpis")
    .select("metric_key, metric_val, updated_at")
    .order("updated_at", { ascending: false })
    .limit(10);

  return new Response(JSON.stringify(data), {
    headers: { "Content-Type": "application/json", "Cache-Control": "s-maxage=30" }
  });
});

